// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the from address, one recipient address and the uint value and the length indicator
    function testFuzz_property(address from, address recipient, uint256 v, uint256 tosLen) public {
        // keep tosLen small but >=1 to ensure at least one call happens
        uint256 len = bound(tosLen, 1, 4);

        // build array of recipients; put the same recipient for simplicity
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = recipient;

        // Deploy a recorder callee that implements the exact selector used by the correct contract
        // and records calls to transferFrom(address,address,uint256). The correct contract will
        // call this function successfully; the mutant (wrong selector) will NOT match and thus
        // the call will fail/return false — causing transfer to revert via require(_s).
        CalleeRecorder rec = new CalleeRecorder();

        // ensure the callee has some ETH so low-level call has nonzero balance if needed (not required)
        vm.deal(address(rec), 1 ether);

        // call transfer and observe it doesn't revert on the correct implementation
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY inputs with non-empty tos, the correct C's transfer
        // completes successfully (ok == true). The mutant that computes a wrong selector
        // will make the external call not match the callee's function and thus fail; the
        // fuzzer can find such an input (the callee we deployed) causing ok == false.
        assertTrue(ok);

        // As an additional check (reading the recorder), ensure that exactly `len` calls were recorded
        // and that each call carried the expected decoded arguments — this reads the observed behavior
        // of C via the helper's public getters (allowed). This further enforces that the correct
        // selector was used and the calls were delivered for every element.
        assertTrue(rec.callCount() == len);
        for (uint i = 0; i < len; i++) {
            (address a_from, address a_to, uint256 a_v) = rec.calls(i);
            assertTrue(a_from == from);
            assertTrue(a_to == recipient);
            assertTrue(a_v == v);
        }
    }
}

// A minimal recording callee that exposes the exact function signature
// transferFrom(address,address,uint256) so that the correct contract's
// selector matches and records the calls. If the caller uses a wrong selector
// (the mutant), this function will not be invoked and the call will fail/return false.
contract CalleeRecorder {
    struct Call { address from; address to; uint256 v; }
    Call[] public recorded;

    // This function matches the selector computed by the correct contract.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        recorded.push(Call({ from: from, to: to, v: v }));
        return true;
    }

    // helpers to read records
    function callCount() external view returns (uint256) { return recorded.length; }
    function calls(uint256 i) external view returns (address, address, uint256) {
        Call storage c = recorded[i];
        return (c.from, c.to, c.v);
    }
}
